"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["5746"],{3918(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>r,contentTitle:()=>h,toc:()=>l,assets:()=>d});var o=JSON.parse('{"id":"m11-autoscaling-gitops/lesson","title":"Lesson: Autoscaling & GitOps \u2014 Operating the Platform","description":"Two things went wrong the same week, and both are the kind of thing that ends up in an incident review with your name on the timeline.","source":"@site/docs/m11-autoscaling-gitops/lesson.md","sourceDirName":"m11-autoscaling-gitops","slug":"/m11-autoscaling-gitops/lesson","permalink":"/305-llmops/docs/m11-autoscaling-gitops/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: Autoscaling & GitOps \u2014 Operating the Platform"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/305-llmops/docs/m10-observability/deep-dive"},"next":{"title":"Lab: Operate the Platform \u2014 Autoscale on Queue Depth, Promote Through Git, Train Under Guardrails","permalink":"/305-llmops/docs/m11-autoscaling-gitops/lab"}}'),i=n(4848),s=n(8453),a=n(7684);let r={sidebar_position:1,title:"Lesson: Autoscaling & GitOps \u2014 Operating the Platform"},h="Autoscaling & GitOps \u2014 Operating the Platform",d={},l=[{value:"Why CPU% is the wrong signal \u2014 kitchen noise versus the queue at the door",id:"why-cpu-is-the-wrong-signal--kitchen-noise-versus-the-queue-at-the-door",level:2},{value:"KEDA \u2014 the ma\xeetre d&#39; who opens the second dining room",id:"keda--the-ma\xeetre-d-who-opens-the-second-dining-room",level:2},{value:"Scale-to-zero, and the cold-start you cannot ignore",id:"scale-to-zero-and-the-cold-start-you-cannot-ignore",level:2},{value:"Why the second engine comes up fast \u2014 the presence-cache, working for you",id:"why-the-second-engine-comes-up-fast--the-presence-cache-working-for-you",level:2},{value:"GitOps where the desired state includes the model version",id:"gitops-where-the-desired-state-includes-the-model-version",level:2},{value:"The promotion lie \u2014 swapping the label on a full jar",id:"the-promotion-lie--swapping-the-label-on-a-full-jar",level:2},{value:"Training as a pipeline step \u2014 the circuit breaker on a shared node",id:"training-as-a-pipeline-step--the-circuit-breaker-on-a-shared-node",level:2},{value:"Where this leaves OpsMate \u2014 and the hand-off to M12",id:"where-this-leaves-opsmate--and-the-hand-off-to-m12",level:2}];function c(e){let t={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",mermaid:"mermaid",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"autoscaling--gitops--operating-the-platform",children:"Autoscaling & GitOps \u2014 Operating the Platform"})}),"\n",(0,i.jsx)(t.p,{children:"Two things went wrong the same week, and both are the kind of thing that ends up in an incident review with your name on the timeline."}),"\n",(0,i.jsx)(t.p,{children:"The first was a surge. A regional outage sent every on-call engineer to OpsMate at once, and the assistant slowed to a crawl right when people needed it. You had autoscaling wired \u2014 a perfectly ordinary HPA on CPU. It never fired. You pulled up the node graph afterward and CPU was sitting at forty percent the whole time. The autoscaler did exactly what you told it to. You told it the wrong thing. Requests were piling up in a queue the CPU number could not see, and one engine sat there at forty percent CPU while forty people waited."}),"\n",(0,i.jsxs)(t.p,{children:["The second was quieter and worse. Someone shipped a new model version \u2014 the fine-tuned OpsMate from M6, packaged and signed. The deploy went green. The change ticket said ",(0,i.jsx)(t.code,{children:"1.0.0"})," \u2192 ",(0,i.jsx)(t.code,{children:"1.0.0-candidate"}),", promoted. And for two days users kept getting the ",(0,i.jsx)(t.em,{children:"old"}),' model\'s answers, and nobody could say for certain which version was actually serving, because the thing that told you the version was a ticket, not a fact you could check. "Promoted" was a sentence someone wrote, not a state of the system.']}),"\n",(0,i.jsx)(t.p,{children:'That is this module. Two jobs. Autoscale on a signal that means something \u2014 the queue at the door, not the noise in the kitchen. And make the serving model version a fact recorded in git, so "what is deployed right now" is a question with a checkable answer and "promote" is a pull request, not a sentence.'}),"\n","\n",(0,i.jsx)(a.A,{src:"decks/m11-concepts.html",title:"M11 \u2014 Autoscaling & GitOps: Operating the Platform"}),"\n",(0,i.jsx)(t.admonition,{title:"Resource path \u2014 8 GB core runs everything required",type:"info",children:(0,i.jsxs)(t.p,{children:["Every required step runs on the ",(0,i.jsx)(t.strong,{children:"8 GB core"})," path: the slim single-node KIND cluster, the model server, the M10 observability stack, KEDA, Argo CD (slim), gitea, and Argo Workflows for the training step. Two things stay small on purpose \u2014 KEDA scales ",(0,i.jsx)(t.code,{children:"1 \u2192 2 \u2192 1"})," (not to a fleet), and the training step runs a ",(0,i.jsx)(t.strong,{children:"smoke profile"})," (",(0,i.jsx)(t.code,{children:"--batch 1 --max-len 256 --max-steps 2"}),") that proves the pipeline without a real fine-tune. Full-fidelity training \u2014 a real multi-epoch run \u2014 is the ",(0,i.jsx)(t.strong,{children:"16 GB / host"})," path (the M6 host run); this module automates the ",(0,i.jsx)(t.em,{children:"pipeline"}),", not a production-grade training job. One heavyweight stack at a time still holds: you drain serving before you train."]})}),"\n",(0,i.jsx)(t.h2,{id:"why-cpu-is-the-wrong-signal--kitchen-noise-versus-the-queue-at-the-door",children:"Why CPU% is the wrong signal \u2014 kitchen noise versus the queue at the door"}),"\n",(0,i.jsx)(t.p,{children:"Start with the mistake, because it is the one almost everyone makes first, and it is the reason the surge in the incident review never triggered a scale-out."}),"\n",(0,i.jsxs)(t.p,{children:["Picture judging how busy a restaurant is by standing outside and listening to the kitchen. Pots banging, the fryer going, chefs calling orders \u2014 loud kitchen, must be busy. But the kitchen noise tells you how hard the cooks are ",(0,i.jsx)(t.em,{children:"working"}),", not how many people are ",(0,i.jsx)(t.em,{children:"waiting"}),". A kitchen can be roaring while the dining room is half empty, and it can be dead quiet while thirty people stand at the door because there is nowhere to seat them. If you want to know whether to open the second dining room, you do not listen to the kitchen. You look at the queue at the door."]}),"\n",(0,i.jsxs)(t.p,{children:["CPU% is the kitchen noise. For a llama.cpp model server, decode saturates ",(0,i.jsx)(t.em,{children:"one core per in-flight request"})," \u2014 one request runs one core hot, and that is it. A second request that arrives with no free slot does not raise CPU; it ",(0,i.jsx)(t.em,{children:"waits"}),". It consumes almost no CPU while it sits in the queue, because it is not doing anything yet \u2014 it is parked. So the exact situation you most need to scale for \u2014 requests arriving faster than the engine can take them \u2014 is the situation where CPU stays flat. During the surge, one engine ran its core hot at forty percent node-average CPU while the queue behind it grew, and the CPU-based HPA, watching the kitchen, heard nothing worth acting on."]}),"\n",(0,i.jsxs)(t.p,{children:["The signal that maps to user pain is the queue at the door: ",(0,i.jsx)(t.strong,{children:"queue depth"}),". And you already know where it lives, because you learned to read it in M10. The model server exports ",(0,i.jsx)(t.code,{children:"llamacpp:requests_deferred"})," \u2014 the count of requests parked because every slot is busy. That is the gauge that climbed while CPU stayed flat. When it rises, requests are not slow, they are ",(0,i.jsx)(t.em,{children:"waiting"}),", and waiting is fixed by adding an engine, not by giving the one engine more CPU it is not blocked on."]}),"\n",(0,i.jsx)(t.admonition,{title:"The habit to carry",type:"tip",children:(0,i.jsxs)(t.p,{children:["Never autoscale an LLM server on CPU%. Decode pins one core per request and a queued request burns almost no CPU, so the metric is flat exactly when you are in trouble. Scale on the queue \u2014 ",(0,i.jsx)(t.code,{children:"llamacpp:requests_deferred"})," \u2014 the same signal M10 taught you to watch. Concurrency (requests in flight against slot capacity) and KV-cache pressure are the other honest LLM-native signals; all three describe demand the engine can feel, which CPU% cannot."]})}),"\n",(0,i.jsx)(t.h2,{id:"keda--the-ma\xeetre-d-who-opens-the-second-dining-room",children:"KEDA \u2014 the ma\xeetre d' who opens the second dining room"}),"\n",(0,i.jsx)(t.p,{children:"So you want to scale on the queue. The mechanism is KEDA, and the cleanest way to hold it in your head is the ma\xeetre d'."}),"\n",(0,i.jsx)(t.p,{children:"A good ma\xeetre d' watches the queue at the door, and when it forms, opens the second dining room. Watch the queue; when it builds, add capacity; when it drains, close the room again. That is the whole control loop, and KEDA is that ma\xeetre d' for your Deployment."}),"\n",(0,i.jsxs)(t.p,{children:["You know what an HPA is, so this module does not re-teach it. The LLM-specific part is ",(0,i.jsx)(t.em,{children:"where the signal comes from and who owns the HPA"}),". KEDA reads your M10 Prometheus series ",(0,i.jsx)(t.strong,{children:"directly"})," \u2014 you hand it the query ",(0,i.jsx)(t.code,{children:"sum(llamacpp:requests_deferred)"})," and a threshold, and it does not need prometheus-adapter's metric-rule language sitting in between. And KEDA does not scale the Deployment itself. It ",(0,i.jsx)(t.strong,{children:"generates an HPA"})," and manages it for you. You write one object, a ",(0,i.jsx)(t.code,{children:"ScaledObject"}),"; KEDA creates a real ",(0,i.jsx)(t.code,{children:"keda-hpa-opsmate-model"})," alongside it. In the lab you will ",(0,i.jsx)(t.code,{children:"kubectl get hpa"})," and see the HPA KEDA built, reading the queue-depth external metric \u2014 both objects, side by side, so the indirection is visible rather than magic."]}),"\n",(0,i.jsx)(t.mermaid,{value:'flowchart LR\n  MODEL["opsmate-model<br/>llamacpp:requests_deferred"] --\x3e|"scraped 5s"| PROM["Prometheus (M10)"]\n  SO["ScaledObject<br/>query: sum(requests_deferred)<br/>threshold: 2"] --\x3e|"KEDA generates"| HPA["keda-hpa-opsmate-model"]\n  PROM --\x3e|"queue depth"| KEDA["KEDA operator"]\n  KEDA --\x3e|"feeds external metric"| HPA\n  HPA --\x3e|"desired replicas"| DEP["Deployment<br/>min 1 \u2192 max 2"]\n  DEP -.->|"more engines drain the queue"| MODEL'}),"\n",(0,i.jsxs)(t.p,{children:["On the 8 GB path you scale ",(0,i.jsx)(t.code,{children:"min 1 / max 2"})," with a threshold of ",(0,i.jsx)(t.code,{children:"2"})," \u2014 more than two parked requests per replica and KEDA adds the second engine. In the lab you drive load until ",(0,i.jsx)(t.code,{children:"requests_deferred"})," climbs, watch ",(0,i.jsx)(t.code,{children:"1 \u2192 2"}),", drain the load, and watch ",(0,i.jsx)(t.code,{children:"2 \u2192 1"}),". Small numbers, but the loop is the real one: watch the queue, open the room, close it again."]}),"\n",(0,i.jsx)(t.h2,{id:"scale-to-zero-and-the-cold-start-you-cannot-ignore",children:"Scale-to-zero, and the cold-start you cannot ignore"}),"\n",(0,i.jsxs)(t.p,{children:["The obvious next thought is: if the ma\xeetre d' can close the second room, why not close the ",(0,i.jsx)(t.em,{children:"first"})," one too when nobody is dining \u2014 scale to zero, pay for nothing? For a stateless web pod, that is often right. For a model server, it is a trap you have to reason about honestly."]}),"\n",(0,i.jsxs)(t.p,{children:["The reason is cold start. A stateless web pod comes back in seconds \u2014 pull a small image, start a process, ready. A model server's cold start is ",(0,i.jsx)(t.em,{children:"image pull plus model load"}),", and the model load is the expensive part: reading the weights off disk into memory and warming the runtime. That is minutes, not seconds. So the math is unforgiving: scale an interactive assistant to zero and the first user after an idle window waits minutes for a reply while the engine loads. That is not a scale event they will forgive."]}),"\n",(0,i.jsxs)(t.p,{children:["The honest rule: scale-to-zero belongs to ",(0,i.jsx)(t.strong,{children:"batch and rare"})," endpoints \u2014 a nightly report generator, an endpoint hit twice a day \u2014 where a cold minute is fine. For an ",(0,i.jsx)(t.strong,{children:"interactive"})," service like OpsMate, keep at least one engine warm. That is why the lab runs ",(0,i.jsx)(t.code,{children:"min 1"}),", not ",(0,i.jsx)(t.code,{children:"min 0"}),"."]}),"\n",(0,i.jsx)(t.admonition,{title:"The scale-to-zero knobs, and why they're quiet here",type:"note",children:(0,i.jsxs)(t.p,{children:["KEDA's ",(0,i.jsx)(t.code,{children:"pollingInterval"})," (how often it queries Prometheus) and ",(0,i.jsx)(t.code,{children:"cooldownPeriod"})," (how long after the last trigger before it scales to zero) only govern the ",(0,i.jsx)(t.code,{children:"0 \u2194 1"})," transition. At ",(0,i.jsx)(t.code,{children:"minReplicaCount: 1"})," KEDA itself warns they are irrelevant \u2014 there is no scale-to-zero to time. They matter the moment you ",(0,i.jsx)(t.em,{children:"do"})," run a batch endpoint at ",(0,i.jsx)(t.code,{children:"min 0"}),"; the Deep Dive takes them apart. Here, ",(0,i.jsx)(t.code,{children:"min 1"})," keeps an engine warm and those knobs sit idle."]})}),"\n",(0,i.jsx)(t.h2,{id:"why-the-second-engine-comes-up-fast--the-presence-cache-working-for-you",children:"Why the second engine comes up fast \u2014 the presence-cache, working for you"}),"\n",(0,i.jsxs)(t.p,{children:["There is a detail in the scale-out that looks like luck and is actually design, and it is worth naming because the ",(0,i.jsx)(t.em,{children:"same"})," mechanism is about to cause trouble two sections from now."]}),"\n",(0,i.jsxs)(t.p,{children:["When KEDA adds the second replica, it comes Ready fast \u2014 far faster than the first engine ever loaded. The reason is the M8 PVC pattern. The model is not baked into the image; an initContainer unpacks it from the signed ModelKit onto a PersistentVolume. The first pod did that unpack. The second pod's init looks at the PVC, sees the model already sitting there, and skips the whole download-and-unpack \u2014 it logs ",(0,i.jsx)(t.code,{children:"model already present on PVC \u2014 skipping unpack"})," and goes straight to serving. The weights are already on disk; the new engine just opens them."]}),"\n",(0,i.jsxs)(t.p,{children:["Call this the ",(0,i.jsx)(t.strong,{children:"presence-cache"}),': the init trusts what is already on the volume and does not re-fetch it. For scale-out that is a feature \u2014 it is exactly why the second dining room opens in seconds. Hold onto it, though, because that same "trust what\'s already on the volume" instinct is about to serve you a ',(0,i.jsx)(t.em,{children:"stale"})," model and swear it is the new one."]}),"\n",(0,i.jsx)(t.h2,{id:"gitops-where-the-desired-state-includes-the-model-version",children:"GitOps where the desired state includes the model version"}),"\n",(0,i.jsx)(t.p,{children:"Now the second failure \u2014 the promotion nobody could verify. The fix is GitOps, and the framing that makes it click is the signed delivery manifest pinned to the door."}),"\n",(0,i.jsxs)(t.p,{children:["Think of a bonded warehouse. What is ",(0,i.jsx)(t.em,{children:"supposed"})," to be inside is not decided by whoever last walked in with a crate; it is decided by the manifest pinned to the door \u2014 the signed paper that says exactly what this building holds. Change the paper through the proper process and the building is made to match it. The paper is the source of truth; the building follows."]}),"\n",(0,i.jsxs)(t.p,{children:["That is GitOps, and you know the shape of it. The twist for a model platform is ",(0,i.jsx)(t.em,{children:"what goes on the manifest"}),". For an ordinary service the desired state is replica counts and an image tag. For OpsMate the desired state includes ",(0,i.jsx)(t.strong,{children:"which signed ModelKit tag is serving"})," \u2014 the model version is not a footnote, it is a line in the manifest. You keep that manifest in a git repo (the lab runs gitea in-cluster as the environment repo), Argo CD watches it, and the cluster is continuously made to match what git says."]}),"\n",(0,i.jsx)(t.mermaid,{value:'flowchart LR\n  DEV["you"] --\x3e|"PR: bump kit tag"| GIT["gitea<br/>opsmate-env repo<br/>(the door manifest)"]\n  GIT --\x3e|"Argo CD watches"| ARGO["Argo CD"]\n  ARGO --\x3e|"reconcile"| CLUSTER["cluster: model-server<br/>points at new tag"]\n  CLUSTER --\x3e|"init unpacks new tag"| PVC["PVC (per-tag dir)"]\n  REVERT["git revert"] -.->|"same loop, backward"| GIT'}),"\n",(0,i.jsxs)(t.p,{children:["So promotion becomes a ",(0,i.jsx)(t.strong,{children:"pull request"})," that bumps the kit tag from ",(0,i.jsx)(t.code,{children:"1.0.0"})," to ",(0,i.jsx)(t.code,{children:"1.0.0-candidate"}),". And rollback becomes ",(0,i.jsx)(t.code,{children:"git revert"}),' \u2014 you undo the commit, Argo reconciles, the cluster goes back. "What is serving?" stops being a ticket you have to trust and becomes ',(0,i.jsx)(t.code,{children:"git log"})," on the env repo. That is the whole point: the version is now a fact, checkable, with an audit trail."]}),"\n",(0,i.jsxs)(t.p,{children:["One operational note you will feel in the lab: Argo's default git poll is around three minutes, so a merged PR does not reconcile instantly. You can wait, or you can force it with the ",(0,i.jsx)(t.code,{children:"argocd.argoproj.io/refresh"})," annotation \u2014 the same job a git webhook would do in a real setup. Poll versus webhook is a latency-versus-plumbing tradeoff; the lab pokes it with the annotation so you are not waiting on the poll."]}),"\n",(0,i.jsx)(t.h2,{id:"the-promotion-lie--swapping-the-label-on-a-full-jar",children:"The promotion lie \u2014 swapping the label on a full jar"}),"\n",(0,i.jsx)(t.p,{children:"Here is where the presence-cache comes back to bite, and it is the exhibit this module is built around. You will hit it live in the lab; meet the shape of it now so you recognize it."}),"\n",(0,i.jsxs)(t.p,{children:["You merge the PR. The tag in git is now ",(0,i.jsx)(t.code,{children:"1.0.0-candidate"}),". Argo reconciles, the model-server pod rolls, everything goes green. And the server keeps serving the ",(0,i.jsx)(t.strong,{children:"old"})," model."]}),"\n",(0,i.jsxs)(t.p,{children:["The analogy is swapping the label on a full jar without changing the contents. You changed the paper on the door \u2014 the manifest says ",(0,i.jsx)(t.code,{children:"candidate"})," \u2014 but the jar on the shelf is still full of the old batch, and nobody emptied it. Mechanically: the pod rolled, the init ran, and the init's idempotency guard \u2014 the presence-cache from a few sections ago \u2014 looked at the PVC, saw ",(0,i.jsx)(t.em,{children:"a"}),' GGUF already there, and skipped the unpack. It did its "trust what\'s on the volume" job perfectly. But "there is a model on the volume" is not the same as "the ',(0,i.jsx)(t.em,{children:"right"}),' model is on the volume." Git claims the new version; the disk holds the old bytes; the server opens the old bytes. The promotion is a lie, and it is a lie told by the exact feature that made scale-out fast.']}),"\n",(0,i.jsxs)(t.p,{children:["The fix is to make the tag part of the path. Instead of one shared model directory, unpack each tag into its ",(0,i.jsx)(t.strong,{children:"own"})," directory \u2014 ",(0,i.jsx)(t.code,{children:"/model/kits/1.0.0/..."}),", ",(0,i.jsx)(t.code,{children:"/model/kits/1.0.0-candidate/..."})," \u2014 and thread the tag through the guard, the unpack, and the server's ",(0,i.jsx)(t.code,{children:"-m"})," flag. Now the guard for ",(0,i.jsx)(t.code,{children:"candidate"})," checks the ",(0,i.jsx)(t.code,{children:"candidate"})," directory, finds it empty, and actually unpacks. The presence-cache still works; it just caches ",(0,i.jsx)(t.em,{children:"per version"})," instead of pretending all versions are one."]}),"\n",(0,i.jsx)(t.admonition,{title:"The model version belongs in git \u2014 and on disk, per version",type:"warning",children:(0,i.jsxs)(t.p,{children:['A green deploy is not a promoted model. If your unpack step keys on "is there ',(0,i.jsx)(t.em,{children:"a"}),' model on the volume," a tag bump will roll the pod and serve the old weights while git swears it shipped the new ones. Make the version part of the path \u2014 one directory per tag \u2014 so the presence check is per version. The tension is the lesson: the cache that makes scale-out fast is the same cache that lies about promotion until you version its key.']})}),"\n",(0,i.jsxs)(t.p,{children:["And the symmetry, because it is the quiet payoff. Once each version has its own directory on the PVC, ",(0,i.jsx)(t.strong,{children:"rollback is instant"}),". ",(0,i.jsx)(t.code,{children:"git revert"})," puts the tag back to ",(0,i.jsx)(t.code,{children:"1.0.0"}),", Argo reconciles, the pod rolls \u2014 and this time the ",(0,i.jsx)(t.code,{children:"1.0.0"})," directory is still sitting on the volume from before, so the init skips the unpack and the old-but-correct engine is Ready in seconds. The same presence-cache that lied during a careless promotion makes a correct rollback nearly free. Cache the version, and both directions win. (There is a second, smaller exhibit waiting in the lab \u2014 the candidate kit ships its GGUF under a different filename, an echo of the M9 packaging lesson \u2014 but the lab walks that one; the promotion lie is the concept to carry.)"]}),"\n",(0,i.jsx)(t.h2,{id:"training-as-a-pipeline-step--the-circuit-breaker-on-a-shared-node",children:"Training as a pipeline step \u2014 the circuit breaker on a shared node"}),"\n",(0,i.jsx)(t.p,{children:'Last job: move the training loop from a thing you run by hand on a laptop (M6) to a step the platform runs \u2014 an Argo Workflow inside the cluster. The concept that matters here is not "how do I run a job." You know that. It is the guardrail, and the analogy is the circuit breaker in a house.'}),"\n",(0,i.jsxs)(t.p,{children:["A house shares one electrical supply across every outlet. Run a space heater, the microwave, and a hair dryer on the same circuit and you brown out the whole house \u2014 the shared supply cannot feed one greedy appliance without starving everything else. The circuit breaker exists to trip ",(0,i.jsx)(t.em,{children:"before"})," that happens, so one appliance can never take down the house."]}),"\n",(0,i.jsxs)(t.p,{children:["A training pod is the space heater. It shares the node's CPU with everything else on that node \u2014 including the Kubernetes control plane. And a fine-tune is not a polite workload; it will take every core it can reach. Run it uncapped on the shared node and it browns out the house: it starved the kube-apiserver so badly the cluster became unrecoverable ",(0,i.jsx)(t.em,{children:"by kubectl"})," \u2014 the very tool you would reach for to stop it needs the apiserver the training pod was strangling. That incident is the Deep Dive's post-mortem; here, take the rule it produced."]}),"\n",(0,i.jsxs)(t.p,{children:["The circuit breaker is a ",(0,i.jsx)(t.strong,{children:"CPU limit"}),". The training pod carries ",(0,i.jsx)(t.code,{children:'limits.cpu: "2"'})," \u2014 it may be slow, but it can never take the node down, because the kernel caps it before it starves the control plane. Alongside the CPU cap: a memory profile sized for the 8 GB path, and the one-heavyweight-at-a-time discipline you have followed all along \u2014 you ",(0,i.jsx)(t.strong,{children:"drain serving first"})," before you train."]}),"\n",(0,i.jsxs)(t.p,{children:["Draining serving has a neat detail. Remember KEDA's ",(0,i.jsx)(t.code,{children:"paused-replicas"})," annotation? You set ",(0,i.jsx)(t.code,{children:'autoscaling.keda.sh/paused-replicas: "0"'}),' on the model server and KEDA pins it to zero replicas \u2014 the same annotation that is normally your "hold scaling steady" lever now doubles as your "get the model engine out of the way so training has the node" lever. Scale the observability stack to zero as well, and the node is clear for the training pod to run under its cap.']}),"\n",(0,i.jsx)(t.admonition,{title:"Drain before you train, on a shared node",type:"tip",children:(0,i.jsxs)(t.p,{children:["A training pod is a heavyweight batch job competing with the control plane for the same cores. Cap it (",(0,i.jsx)(t.code,{children:"limits.cpu"}),") so it can never starve the apiserver, and drain the serving stack first \u2014 pause the model server with KEDA's ",(0,i.jsx)(t.code,{children:'paused-replicas: "0"'})," and scale observability to zero \u2014 so one heavyweight workload runs at a time. On the 8 GB path this is a smoke profile that proves the pipeline; a real fine-tune is the 16 GB / host path."]})}),"\n",(0,i.jsx)(t.h2,{id:"where-this-leaves-opsmate--and-the-hand-off-to-m12",children:"Where this leaves OpsMate \u2014 and the hand-off to M12"}),"\n",(0,i.jsxs)(t.p,{children:["OpsMate is now ",(0,i.jsx)(t.strong,{children:"v2.5"}),", operated like a platform. It autoscales on a signal that means something \u2014 queue depth, the queue at the door, not the kitchen noise of CPU%. Its model version is a fact in git: promoted by pull request, rolled back by ",(0,i.jsx)(t.code,{children:"git revert"}),", and \u2014 once the presence-cache is versioned per tag \u2014 actually the version git says it is. And its training loop is a pipeline step with a circuit breaker, so automating the fine-tune can never brown out the cluster it runs on."]}),"\n",(0,i.jsxs)(t.p,{children:["That sets up M12 directly. You can scale it, you can promote and roll back its model, you can retrain it \u2014 but you have not yet put a front door on it. M12 adds the gateway: the single entry point where you run evals as a promotion gate (so a candidate model has to ",(0,i.jsx)(t.em,{children:"earn"})," the tag bump you learned to make here), enforce guardrails, and control who and what reaches the model. You have learned to operate the platform. Next you learn to govern what goes through its door."]})]})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},7684(e,t,n){n.d(t,{A:()=>s});var o=n(4848);n(6540);var i=n(6497);function s({src:e,title:t="Slides"}){let n=(0,i.Ay)(e);return(0,o.jsxs)("div",{className:"deck_nWXz",children:[(0,o.jsxs)("div",{className:"bar_dOoE",children:[(0,o.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,o.jsx)("a",{className:"full_PrDQ",href:n,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,o.jsx)("div",{className:"frame_M4DO",children:(0,o.jsx)("iframe",{src:n,title:t,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var o=n(6540);let i={},s=o.createContext(i);function a(e){let t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);